const listExpiredRunLeases = `-- name: ListExpiredRunLeases :many
SELECT id, agent_definition_id, agent_name, project_id, status, input, output, error, attempt, max_attempts, runtime_id, run_token_hash, lease_expires_at, cancel_requested, total_input_tokens, total_output_tokens, total_cost_usd, created_by, created_at, started_at, finished_at, updated_at, workflow_run_id, idempotency_key, model_override, context FROM agent_runs
WHERE status = 'running' AND lease_expires_at < now()
ORDER BY lease_expires_at
FOR UPDATE SKIP LOCKED
LIMIT 50
`

func (q *Queries) ListExpiredRunLeases(ctx context.Context) ([]AgentRun, error) {
	rows, err := q.db.Query(ctx, listExpiredRunLeases)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AgentRun{}
	for rows.Next() {
		var i AgentRun
		if err := rows.Scan(
			&i.ID,
			&i.AgentDefinitionID,
			&i.AgentName,
			&i.ProjectID,
			&i.Status,
			&i.Input,
			&i.Output,
			&i.Error,
			&i.Attempt,
			&i.MaxAttempts,
			&i.RuntimeID,
			&i.RunTokenHash,
			&i.LeaseExpiresAt,
			&i.CancelRequested,
			&i.TotalInputTokens,
			&i.TotalOutputTokens,
			&i.TotalCostUsd,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.StartedAt,
			&i.FinishedAt,
			&i.UpdatedAt,
			&i.WorkflowRunID,
			&i.IdempotencyKey,
			&i.ModelOverride,
			&i.Context,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

